#nullable enable
using JetBrains.ReSharper.Psi;
using JetBrains.ReSharper.Psi.SourceGenerators;

namespace DotNetAnalysisAndRefactoringMcp;

/// <summary>
///   A file a source generator wrote, as the text answers name it where they write a path for any other file:
///   <c>[generated by Shapes.Generators.SwatchGenerator] Swatch.g.cs</c>, the generator and the name it gave the file.
/// </summary>
/// <remarks>
///   Rider holds such a file in memory, with no path, so its path can't say where it is. Until 2026-11-26 the answers
///   said only <c>[generated]</c> of a declaration there, and <c>find_usages</c> left out the usages there.
/// </remarks>
static class GeneratedFile
{
   /// <summary>Its name, <c>[generated]</c> for another file with no path, and nothing for a file with a path.</summary>
   public static string? NameOf(IPsiSourceFile file) =>
      file is ISourceGeneratorOutputFile generated ? $"[generated by {generated.GeneratorName}] {generated.HintName}"
    : string.IsNullOrEmpty(file.GetLocation().FullPath) ? "[generated]"
    : null;

   /// <summary>What the text answers write where they write a file's full path: its <see cref="NameOf">name</see> for a file with no path.</summary>
   public static string NameOrPathOf(IPsiSourceFile file) => NameOf(file) ?? file.GetLocation().FullPath;
}
